import json
def fuse_conv_bn(graph):
    nodes=graph.get("nodes",[]);new=[];skipped=set()
    for i,n in enumerate(nodes):
        if i in skipped:continue
        if n["op"]=="Conv" and i+1<len(nodes) and nodes[i+1]["op"]=="BatchNormalization":
            new.append({"op":"ConvBN","input":n["input"],"output":nodes[i+1]["output"],"fused":True})
            skipped.add(i+1)
        else:new.append(n)
    return {"nodes":new}
def constant_folding(graph):
    return graph
def optimize_onnx(graph):
    g=fuse_conv_bn(graph)
    g=constant_folding(g)
    g["optimized"]=True
    return g

def parse_stages(df):
    stages=[];cur=None
    for line in df.split("\n"):
        line=line.strip()
        if not line:continue
        if line.upper().startswith("FROM"):
            cur={"from":line[5:].strip(),"cmds":[]};stages.append(cur)
        elif cur is not None:cur["cmds"].append(line)
    return stages
def multi_stage_build(df):
    stages=parse_stages(df);result=[]
    for i,s in enumerate(stages):
        stage_size=len(s["cmds"])*5
        result.append({"stage":i,"base":s["from"],"layers":len(s["cmds"]),"size_mb":stage_size,"final":i==len(stages)-1})
    return {"stages":result,"total_size":sum(r["size_mb"]for r in result)}

import numpy as np
def quantize_fp16(w):
    w=np.array(w);return w.astype(np.float16)
def quantize_int8(w):
    w=np.array(w)
    absmax=np.max(np.abs(w))
    scale=127/absmax;q=np.clip(np.round(w*scale),-127,127)
    return {"quantized":q.astype(np.int8),"scale":scale}
def quantization_error(orig,quant):
    orig=np.array(orig)
    if isinstance(quant,dict):deq=quant["quantized"].astype(float)/quant["scale"]
    else:deq=quant.astype(float) if quant.dtype==np.float16 else quant
    mse=np.mean((orig-deq)**2)
    max_err=np.max(np.abs(orig-deq))
    return {"mse":round(float(mse),6),"max_error":round(float(max_err),6)}

def continuous_batching(requests,max_batch=4,max_len=10):
    running=[];pending=list(requests);completed=[];step=0
    while (running or pending) and step<max_len*len(requests):
        step+=1
        while len(running)<max_batch and pending:
            running.append({"id":pending.pop(0),"tokens":[0],"done":False})
        for r in running[:]:
            if not r["done"]:
                r["tokens"].append(r["tokens"][-1]+1)
                if len(r["tokens"])>=max_len:
                    r["done"]=True;completed.append(r["id"]);running.remove(r)
    return {"completed":completed,"steps":step,"throughput":round(len(completed)/step,4)}
